def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - np.fmin(bins, item)
    normalized_remaining = remaining / (bins + 1e-8)
    imbalance_penalty = np.abs(bins - np.mean(bins)) / (np.mean(bins) + 1e-8)
    scores = normalized_remaining - 0.5 * imbalance_penalty
    return np.clip(scores, 0, 1)
